
/*
  JAGREY SALES — Shopping Cart & WhatsApp Orders

    IMPORTANT:
      1. Replace WHATSAPP_NUMBER with your business number.
        2. Update product prices and images before publishing.
          3. Prices below are sample prices, not verified selling prices.
          */

          const WHATSAPP_NUMBER = "919993717621";

          const products = [
            {
                id: 1,
                    name: "Traditional Gur",
                        description: "Classic jaggery for everyday sweetness.",
                            price: 80,
                                unit: "500 g",
                                    tag: "BESTSELLER",
                                        image: "https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=600&q=80"
                                          },
                                            {
                                                id: 2,
                                                    name: "Desi Gud",
                                                        description: "A traditional choice for your kitchen.",
                                                            price: 150,
                                                                unit: "1 kg",
                                                                    tag: "EVERYDAY PICK",
                                                                        image: "https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=600&q=80"
                                                                          },
                                                                            {
                                                                                id: 3,
                                                                                    name: "Premium Gur",
                                                                                        description: "A premium option for gifting and sharing.",
                                                                                            price: 200,
                                                                                                unit: "1 kg",
                                                                                                    tag: "PREMIUM",
                                                                                                        image: "https://images.unsplash.com/photo-1609501676725-7186f734a1c8?auto=format&fit=crop&w=600&q=80"
                                                                                                          },
                                                                                                            {
                                                                                                                id: 4,
                                                                                                                    name: "Bulk Jaggery",
                                                                                                                        description: "For retailers, shops and wholesale enquiries.",
                                                                                                                            price: 0,
                                                                                                                                unit: "Bulk order",
                                                                                                                                    tag: "WHOLESALE",
                                                                                                                                        image: "https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=600&q=80"
                                                                                                                                          }
                                                                                                                                          ];

                                                                                                                                          const cart = {};

                                                                                                                                          const productGrid = document.getElementById("productGrid");
                                                                                                                                          const cartCount = document.getElementById("cartCount");
                                                                                                                                          const cartDrawer = document.getElementById("cartDrawer");
                                                                                                                                          const cartOverlay = document.getElementById("cartOverlay");
                                                                                                                                          const cartItems = document.getElementById("cartItems");
                                                                                                                                          const cartTotal = document.getElementById("cartTotal");
                                                                                                                                          const checkoutButton = document.getElementById("checkoutButton");

                                                                                                                                          function formatPrice(price) {
                                                                                                                                            return new Intl.NumberFormat("en-IN", {
                                                                                                                                                style: "currency",
                                                                                                                                                    currency: "INR",
                                                                                                                                                        maximumFractionDigits: 0
                                                                                                                                                          }).format(price);
                                                                                                                                                          }

                                                                                                                                                          function renderProducts() {
                                                                                                                                                            productGrid.innerHTML = products.map(product => `
                                                                                                                                                                <article class="product-card">
                                                                                                                                                                      <div class="product-image">
                                                                                                                                                                              <img
                                                                                                                                                                                        src="${product.image}"
                                                                                                                                                                                                  alt="${product.name}"
                                                                                                                                                                                                            loading="lazy"
                                                                                                                                                                                                                      onerror="this.onerror=null;this.src='https://placehold.co/600x450/f5eadb/3b2418?text=Jagrey+Sales';"
                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                      <span class="product-tag">${product.tag}</span>
                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                  <div class="product-info">
                                                                                                                                                                                                                                                          <h3>${product.name}</h3>
                                                                                                                                                                                                                                                                  <p>${product.description}</p>

                                                                                                                                                                                                                                                                          <div class="product-buy">
                                                                                                                                                                                                                                                                                    <span class="price">
                                                                                                                                                                                                                                                                                                ${product.price ? formatPrice(product.price) : "Ask for price"}
                                                                                                                                                                                                                                                                                                            <small>${product.price ? `/ ${product.unit}` : ""}</small>
                                                                                                                                                                                                                                                                                                                      </span>

                                                                                                                                                                                                                                                                                                                                <button
                                                                                                                                                                                                                                                                                                                                            class="add-button"
                                                                                                                                                                                                                                                                                                                                                        data-product-id="${product.id}"
                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                              ${product.price ? "+ Add to cart" : "Enquire ↗"}
                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                          </article>
                                                                                                                                                                                                                                                                                                                                                                                                            `).join("");
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                            function addToCart(id) {
                                                                                                                                                                                                                                                                                                                                                                                                              const product = products.find(item => item.id === id);
                                                                                                                                                                                                                                                                                                                                                                                                                if (!product) return;

                                                                                                                                                                                                                                                                                                                                                                                                                  if (!product.price) {
                                                                                                                                                                                                                                                                                                                                                                                                                      openWhatsApp(
                                                                                                                                                                                                                                                                                                                                                                                                                            `Hello Jagrey Sales! I am interested in ${product.name}. Please share your wholesale prices and available quantities.`
                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                        if (cart[id]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            cart[id].quantity += 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                  cart[id] = { ...product, quantity: 1 };
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                      renderCart();
                                                                                                                                                                                                                                                                                                                                                                                                                                                        openCart();
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                        function changeQuantity(id, change) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!cart[id]) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                            cart[id].quantity += change;

                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (cart[id].quantity <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  delete cart[id];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      renderCart();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function renderCart() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const items = Object.values(cart);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const totalItems = items.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (sum, item) => sum + item.quantity,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const totalPrice = items.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (sum, item) => sum + item.price * item.quantity,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cartCount.textContent = totalItems;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cartTotal.textContent = formatPrice(totalPrice);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      checkoutButton.disabled = items.length === 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (items.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cartItems.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="empty-cart">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style="font-size:40px;margin-bottom:12px">🛒</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <strong>Your cart is waiting for some sweetness!</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p style="margin-top:8px">Add your favourite products to get started.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cartItems.innerHTML = items.map(item => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="cart-item">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h3>${item.name}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <small>${item.unit} · ${formatPrice(item.price)} each</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="quantity-controls">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button data-change="-1" data-id="${item.id}" aria-label="Decrease quantity">−</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span>${item.quantity}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button data-change="1" data-id="${item.id}" aria-label="Increase quantity">+</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="cart-item-right">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <strong>${formatPrice(item.price * item.quantity)}</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `).join("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function openCart() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cartDrawer.classList.add("open");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cartOverlay.classList.add("active");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.body.style.overflow = "hidden";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function closeCart() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cartDrawer.classList.remove("open");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cartOverlay.classList.remove("active");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.body.style.overflow = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function openWhatsApp(message) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!/^91\d{10}$/.test(WHATSAPP_NUMBER)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      alert(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Please configure your WhatsApp number in script.js first. Use country code 91 followed by your 10-digit mobile number."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const url =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(message)}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              window.open(url, "_blank", "noopener,noreferrer");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Product actions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              productGrid.addEventListener("click", event => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const button = event.target.closest("[data-product-id]");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!button) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    addToCart(Number(button.dataset.productId));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Cart quantity controls
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cartItems.addEventListener("click", event => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const button = event.target.closest("[data-change]");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!button) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          changeQuantity(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Number(button.dataset.id),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Number(button.dataset.change)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("cartButton").addEventListener("click", openCart);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("closeCart").addEventListener("click", closeCart);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cartOverlay.addEventListener("click", closeCart);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    checkoutButton.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const items = Object.values(cart);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!items.length) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const orderLines = items.map(item =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `• ${item.name} (${item.unit}) × ${item.quantity} = ${formatPrice(item.price * item.quantity)}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const total = items.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (sum, item) => sum + item.price * item.quantity,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const message = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "Namaste Jagrey Sales!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "I would like to place an order:",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ...orderLines,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      `Estimated product total: ${formatPrice(total)}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "Please confirm availability, delivery charges and the final amount.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "My name and delivery address: "
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ].join("\n");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      openWhatsApp(message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Mobile navigation
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const menuToggle = document.getElementById("menuToggle");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const nav = document.getElementById("nav");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      menuToggle.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const isOpen = nav.classList.toggle("active");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          menuToggle.setAttribute("aria-expanded", String(isOpen));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          nav.querySelectorAll("a").forEach(link => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            link.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                nav.classList.remove("active");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    menuToggle.setAttribute("aria-expanded", "false");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // General contact button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.getElementById("contactWhatsApp").addEventListener("click", event => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        event.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          openWhatsApp(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "Namaste Jagrey Sales! I would like to know more about your jaggery products, prices and delivery options."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Footer year
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("year").textContent = new Date().getFullYear();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Initial page rendering
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderProducts();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderCart();
